export const BODY: string = "\n<p>نفس الصورة قد تبدو مثالية على هاتفك ومائلة تمامًا على موقع: لم يتغير شيء في الملف بين العرضين، ومع ذلك تظهر الصورة مدورة.</p>\n<p>السبب معلومة صغيرة تسمى اتجاه EXIF: إنها ملاحظة داخل الملف تسجل كيف كانت الكاميرا ممسوكة، وليست كل البرامج تقرأها.</p>\n<p>يشرح هذا المقال كيف يعمل اتجاه EXIF ولماذا يفشل وكيف تصحح صورة إلى الأبد، لتُعرض جيدًا في كل عارض ونموذج وتطبيق.</p>\n<h2 id=\"what-is-exif-orientation\">ما اتجاه EXIF؟</h2>\n<p>EXIF هو معيار البيانات الوصفية الذي تكتبه الكاميرات والهواتف في كل صورة: يسجل موديل الكاميرا وضبط التعريض والتاريخ واتجاه الجهاز.</p>\n<p>حقل الاتجاه رقم واحد من 1 إلى 8: كل قيمة تصف مزيجًا من دوران وانعكاس، مثل مدورة 90 درجة في اتجاه عقارب الساعة أو مقلوبة أفقيًا. وعندما تلتقط صورة بهاتف مائل، يلتقط المستشعر البكسلات في اتجاه ثابت: ثم يكتب الهاتف قيمة اتجاه تقول كيف يجب أن تُعرض الصورة.</p>\n<p>والعارضات التي تفهم EXIF تدور الصورة على الشاشة حسب تلك القيمة: والتي لا تفهمها تُظهر البكسلات كما هي، ولهذا تبدو الصورة مائلة.</p>\n<h2 id=\"the-eight-orientation-values\">قيم الاتجاه الثماني موضحة ببساطة</h2>\n<p>القيمة 1 تعني أن الصورة مستقيمة أصلًا ولا تحتاج دورانًا: معظم الصور الملتقطة بهاتف في وضع عادي تحمل هذه القيمة.</p>\n<p>والقيم 3 و6 و8 تصف دورانًا: القيمة 3 تعني أن الصورة مقلوبة رأسًا على عقب، والقيمة 6 أنها تحتاج دوران 90 درجة في اتجاه عقارب الساعة، والقيمة 8 أنها تحتاج 90 درجة عكس عقارب الساعة. والقيم 2 و4 و5 و7 تضيف انعكاسًا: تظهر مع الكاميرات الأمامية وبعض الماسحات، حيث تُقلب الصورة إضافة إلى دورانها.</p>\n<p>لا تحتاج حفظ هذه الأرقام: ما يهم هو النمط: صورة تبدو سيئة في عارض وجيدة في آخر غالبًا لها قيمة اتجاه يتجاهلها أحدهما.</p>\n<h2 id=\"why-phones-store-orientation-this-way\">لماذا تحفظ الهواتف الاتجاه بدل تدوير البكسلات</h2>\n<p>تدوير البكسلات الحقيقية يستغرق وقتًا وقوة معالجة: كتابة رقم واحد في البيانات الوصفية فورية، فتختار الهواتف الطريق السريع وتترك العمل للعارضات.</p>\n<p>هذا التصميم يحافظ أيضًا على بيانات المستشعر الأصلية سليمة: يبقى الملف بالضبط كما التقطته الكاميرا، وملاحظة الاتجاه تخبر كل برنامج كيف يقدمه. ولمعظم الناس يعمل هذا دون أن يلاحظوا: المعارض والمتصفحات وتطبيقات التواصل الاجتماعي الحديثة تقرأ قيمة الاتجاه، فتبدو الصور جيدة دون أن يفعل أحد شيئًا.</p>\n<p>والمشكلة تظهر في حواف النظام: برامج قديمة ونماذج رفع وخدمات طباعة وعارضات بسيطة لم تتعلم أبدًا قراءة الملاحظة.</p>\n<h2 id=\"where-orientation-breaks\">أين ينكسر الاتجاه عمليًا</h2>\n<p>نماذج الرفع هي أكثر نقطة فشل شيوعًا: بوابة توظيف أو موقع رسمي قد يعرض صورتك مائلة مع أنها تبدو جيدة في معرضك، لأن النموذج يتجاهل EXIF.</p>\n<p>وعملاء البريد حالة أخرى: بعض العملاء القدامى يعرضون الصور المرفقة في اتجاهها الأصلي، فيرى المتلقي صورة مائلة بدت جيدة لمن أرسلها. وخدمات الطباعة قد تفشل أيضًا: صورة مطبوعة من ملف يعتمد على ملاحظة الاتجاه قد تخرج مدورة إذا لم يقرأ برنامج الطباعة البيانات الوصفية.</p>\n<p>وحتى بعض منصات التواصل الاجتماعي واجهت هذه المشكلة في الماضي: صورة رُفعت من الهاتف قد تظهر مدورة في منشور، مع أن نفس الملف بدا جيدًا في المعرض.</p>\n<h2 id=\"detecting-an-orientation-problem\">كيف تعرف إن كان الاتجاه هو مشكلتك</h2>\n<p>العرض المميز هو عدم الاتساق: إذا بدا نفس الملف جيدًا في مكان وسيئًا في آخر، فالأرجح أن بيانات الاتجاه الوصفية هي السبب، لا ملف تالف.</p>\n<p>افتح الصورة في برنامجين مختلفين: إذا أظهرها معرض هاتفك جيدًا وأظهرها عارض حاسوب مائلة، فملاحظة EXIF يقرأها أحدهما ويتجاهلها الآخر. ودليل آخر هو اتجاه الخطأ: مشاكل الاتجاه تدور دائمًا 90 أو 180 درجة، أبدًا زاوية صغيرة مثل ثلاث درجات، التي تشير بالأحرى إلى كاميرا مائلة.</p>\n<p>وراجع الملف على جهاز ثانٍ إن استطعت: صورة مائلة في كل مكان، بما فيه معرضك، لها بكسلات مدورة فعلًا وتحتاج تصحيح دوران عادي.</p>\n<h2 id=\"fixing-orientation-permanently\">كيف تصحح الاتجاه إلى الأبد</h2>\n<p>الحل الدائم هو تدوير البكسلات الحقيقية وإعادة تعيين قيمة الاتجاه إلى 1: وبعد فعل ذلك، يُعرض الملف جيدًا في كل عارض، يقرأ EXIF أم لا.</p>\n<p>أداة <a href=\"/ar/tadweer-wa-qalb-as-sura/\">تدوير وقلب الصور</a> تفعل هذا بالضبط: عندما تدور صورة وتنزلها، يكون للملف المصدر بكسلات موجهة صحيحًا وملصق اتجاه نظيف. وهذا أفضل من الاعتماد على أن العارضات تفسر الملاحظة: ملف مصحح يعمل في برامج قديمة ونماذج رفع وخدمات طباعة لم تتعلم أبدًا قراءة EXIF.</p>\n<p>واحتفظ بالملف الأصلي قبل تصحيحه، في حال احتجت النسخة السليمة يومًا: والملف المصحح هو الذي يجب أن تشاركه وترفعه وتطبعه.</p>\n<h2 id=\"orientation-vs-rotation\">بيانات الاتجاه الوصفية مقابل دوران حقيقي</h2>\n<p>بيانات الاتجاه الوصفية اقتراح حول كيفية عرض الصورة: والدوران الحقيقي يغيّر البكسلات نفسها، فالاقتراح لم يعد لازمًا.</p>\n<p>فكر فيه كملاحظة لاصقة على لوحة تقول \"هذا الجانب لأعلى\": عارض يقرأ الملاحظة يعلّق اللوحة صحيحًا، بينما عارض يتجاهلها يعلّقها مائلة. وتدوير البكسلات كإعادة رسم اللوحة مستقيمة: الملاحظة اللاصقة لم تعد لازمة، وكل عارض يعرض الصورة صحيحًا.</p>\n<p>ولهذا تصحيح دوران منفذ جيدًا دائم: يزيل الاعتماد على أن تتفق كل البرامج على حقل بيانات وصفية.</p>\n<h2 id=\"selfies-and-mirroring\">صور سيلفي وانعكاسات وقيم اتجاه</h2>\n<p>الكاميرات الأمامية تضيف التفافًا إلى قصة الاتجاه: كثير من الهواتف تحفظ صورة معكوسة وتسجل قلبًا في قيمة الاتجاه، فتبدو الصورة جيدة في المعرض.</p>\n<p>وعندما يتجاهل عارض تلك القيمة، تظهر السيلفي معكوسة: نص على قميص يُقرأ عكسيًا، وفرق الشعر يقع على الجانب الخطأ من الرأس. والحل قلب أفقي لا دوران: القلب يعكس البكسلات مجددًا، والملف المصدر لم يعد يعتمد على ملاحظة الاتجاه ليبدو جيدًا.</p>\n<p>وإذا احتاجت سيلفي قلبًا ودورانًا معًا، افعل القلب أولًا ثم الدوران: راجع المعاينة بعد كل خطوة لترى بالضبط ما تغيّر.</p>\n<h2 id=\"exif-and-privacy\">اتجاه EXIF والخصوصية</h2>\n<p>حقل الاتجاه هو فقط جزء من بيانات EXIF الوصفية: نفس الملف قد يحمل أيضًا إحداثيات GPS وموديل الكاميرا والتاريخ الذي التُقطت فيه الصورة.</p>\n<p>تلك البيانات الإضافية مشكلة خصوصية عندما تشارك صورًا علنًا: صورة منشورة عبر الإنترنت قد تكشف أين التُقطت، مع أن الصورة نفسها لا تُظهر شيئًا مميزًا. وتدوير صورة في أداة CompressMyPic يزيل بيانات GPS أثناء التصدير: يُصحح الاتجاه ويُزال سجل الموقع في نفس الخطوة.</p>\n<p>وإذا أردت مراجعة ما تكشفه صورة قبل مشاركتها، استخدم <a href=\"/ar/arid-bayanat-as-sura/\">عارض بيانات الصور الوصفية</a> لفحص حقول EXIF: ولإزالتها تمامًا، استخدم أداة <a href=\"/ar/izala-bayanat-as-sura/\">إزالة البيانات الوصفية</a>.</p>\n<h2 id=\"orientation-in-different-formats\">الاتجاه في JPG وPNG وWebP</h2>\n<p>JPG هو حيث مشاكل الاتجاه أكثر شيوعًا، لأن كل الهواتف تقريبًا تحفظ الصور كـJPG ببيانات EXIF كاملة: ويُكتب حقل الاتجاه افتراضيًا.</p>\n<p>ملفات PNG قد تحمل أيضًا بيانات EXIF، لكن كثيرًا من أدوات PNG تزيلها أو لا تكتبها أبدًا: لقطة شاشة PNG نادرًا لها مشكلة اتجاه، لأن لقطات الشاشة ليس لها اتجاه كاميرا. وWebP يدعم أيضًا اتجاه EXIF: المتصفحات الحديثة تقرأه جيدًا، لكن أدوات قديمة تحوّل WebP إلى JPG تفقد أحيانًا قيمة الاتجاه وتنتج صورة مائلة.</p>\n<p>وHEIC، الصيغة التي تستخدمها آيفونات الأحدث، تحفظ الاتجاه أيضًا: تحويل HEIC إلى JPG دون التعامل مع قيمة الاتجاه سبب شائع لصور مائلة بعد التحويل.</p>\n<h2 id=\"orientation-after-conversion\">مشاكل الاتجاه بعد تحويل الصيغة</h2>\n<p>تحويل صورة من صيغة إلى أخرى قد يكسر اتجاهها: قد ينسخ المحول البكسلات لكنه يفقد ملاحظة EXIF، تاركًا صورة مائلة دون أي سجل لكيف يجب أن تُعرض.</p>\n<p>هذا شائع عند تحويل HEIC إلى JPG: ملف الآيفون يحمل قيمة اتجاه، ومحول يتجاهلها ينتج JPG يبدو مدورًا في كل عارض. والسير الأكثر أمانًا هو تصحيح الاتجاه أولًا ثم التحويل: دوّر الصورة في أداة <a href=\"/ar/tadweer-wa-qalb-as-sura/\">تدوير وقلب الصور</a> ونزّل الملف المصحح وفقط عندها حوّله إلى صيغة أخرى.</p>\n<p>وإذا بدا ملف محول أصلًا مائلًا، دوّر الملف المحول مباشرة: ما يهم الآن هو البكسلات، وتصحيح دوران عادي سيصلحها.</p>\n<h2 id=\"orientation-and-social-media\">الاتجاه في وسائل التواصل الاجتماعي وتطبيقات المراسلة</h2>\n<p>معظم منصات التواصل الاجتماعي الكبيرة تقرأ اتجاه EXIF جيدًا أصلًا: صورة رُفعت من الهاتف تظهر عادة مستقيمة في منشور أو قصة أو صورة شخصية.</p>\n<p>وتطبيقات المراسلة أكثر تنوعًا: بعضها يقرأ قيمة الاتجاه، بينما أخرى تُظهر البكسلات كما هي، فتظهر نفس الصورة جيدة في تطبيق ومائلة في آخر. وصور الشخصية حالة خاصة: كثير من المنصات تقص صورًا شخصية في مربع أو دائرة، وصورة مصدر مائلة تنتج قصًا سيئ التأطير مع أن الاتجاه يُقرأ صحيحًا.</p>\n<p>صحّح الاتجاه قبل الرفع إلى أي مكان مهم: ملف مصحح يزيل الشك ويبدو نفسه في كل المنصات.</p>\n<h2 id=\"common-myths\">أساطير شائعة عن اتجاه الصور</h2>\n<p>أسطورة أن صورة مائلة تالفة: ليست كذلك: البكسلات سليمة والملف سليم؛ فقط تعليمة العرض تُتجاهل.</p>\n<p>وأسطورة أخرى أن إعادة حفظ الملف في محرر تصححه دائمًا: بعض المحررين يحافظون على قيمة الاتجاه سليمة، فيخرج الملف مائلًا كما دخل. وأسطورة ثالثة أن كل البرامج الحديثة تقرأ EXIF: معظمها يفعل، لكن نماذج الرفع وأكشاك الطباعة والأنظمة المدمجة غالبًا متأخرة بسنوات، وهي الأماكن التي يهم فيها الأمر أكثر.</p>\n<p>والقاعدة الموثوقة بسيطة: إذا كانت صورة مهمة، صحّح البكسلات: ملف ببكسلات صحيحة وملصق اتجاه نظيف يعمل في كل مكان، دون أساطير في المنتصف.</p>\n<h2 id=\"orientation-in-print-services\">الاتجاه في خدمات الطباعة والأكشاك</h2>\n<p>أكشاك الطباعة من أسوأ المذنبين في تجاهل اتجاه EXIF: صورة تبدو مثالية على هاتفك قد تُطبع مائلة في كشك يقرأ فقط البكسلات الأصلية.</p>\n<p>والحل تصحيح الملف قبل المشي إلى الكشك: دوّر البكسلات في الأداة ونزّل الملف المصحح واطبع من تلك النسخة بدل الأصل. وخدمات الطباعة عبر الإنترنت أفضل لكنها ليست مثالية: بعضها يقرأ ملاحظة الاتجاه جيدًا، بينما أخرى تعتمد على أبعاد الملف، فملف مصحح هو الخيار الأكثر أمانًا.</p>\n<p>ولأي شيء تدفع لطباعته، راجع نسخة اختبار أولًا دائمًا: نسخة اختبار واحدة تكلف قليلًا، بينما طلب كامل من مطبوعات مائلة يكلف أكثر بكثير.</p>\n<h2 id=\"orientation-and-backup-services\">الاتجاه وخدمات النسخ الاحتياطي السحابية</h2>\n<p>خدمات النسخ الاحتياطي السحابية تحافظ عادة على بيانات EXIF، فصورة نُسخت احتياطيًا واستُعيدت تحافظ على ملاحظة اتجاهها: المشكلة ليست النسخ الاحتياطي، بل البرامج التي تفتح الملف بعدها.</p>\n<p>ونقل صور بين خدمات قد يزيل البيانات الوصفية: ملف نُزّل من خدمة سحابية ورُفع إلى أخرى قد يفقد قيمة اتجاهه في الطريق. وصحّح الاتجاه قبل أرشفة صور مهمة: ملف ببكسلات صحيحة وملصق اتجاه نظيف ينجو من أي عدد نقل دون تغيير مظهره.</p>\n<p>ولصور عائلية وذكريات ممسوحة، هذه الخطوة تهم أكثر من أي وقت: صورة مؤرشفة مائلة قد تبقى مائلة لسنوات قبل أن يلاحظها أحد ويصححها.</p>\n<h2 id=\"orientation-in-old-software\">الاتجاه في برامج قديمة وأنظمة مدمجة</h2>\n<p>عارضات صور قديمة وشاشات سيارات وإطارات صور رقمية غالبًا تتجاهل EXIF تمامًا: بُنيت قبل أن تصبح بيانات الاتجاه الوصفية قياسية.</p>\n<p>إطار صور رقمي يعرض صور عطلاتك مائلة ليس مكسورًا: ببساطة يعرض البكسلات كما سجلتها الكاميرا، دون قراءة ملاحظة الاتجاه. ونفس الشيء ينطبق على بعض أنظمة صور طبية وصناعية، التي تعرض الملفات كما هي محفوظة بالضبط: ملف مصحح يعمل في هذه الأنظمة، بينما ملف يعتمد على الملاحظة لا يعمل.</p>\n<p>وعندما يجب أن تُعرض صورة على جهاز لا تتحكم فيه، صحّح البكسلات: إنه النهج الوحيد الذي يعمل في كل الأجهزة، قديمة أو جديدة.</p>\n<h2 id=\"orientation-testing-checklist\">قائمة تحقق سريعة قبل مشاركة صورة</h2>\n<p>افتح الصورة في برنامجين مختلفين قبل مشاركتها: إذا بدت جيدة في الاثنين، فالاتجاه غالبًا جيد، والملف آمن للإرسال.</p>\n<p>راجع الصورة على جهاز ثانٍ إن استطعت: هاتف وحاسوب يقرآن الاتجاه بشكل مختلف، فملف يبدو جيدًا في الاثنين صحيح فعلًا. وصحّح البكسلات عندما تشك: التدوير في أداة <a href=\"/ar/tadweer-wa-qalb-as-sura/\">تدوير وقلب الصور</a> يستغرق ثوانٍ، وملف مصحح يزيل كل عدم يقين حول كيف ستُعرض.</p>\n<p>واحفظ الملف الأصلي في مجلد أرشيف: النسخة المصححة هي التي يجب أن تشاركها، لكن الأصل يحافظ على بيانات المستشعر سليمة في حال احتجتها يومًا.</p>\n<p>للخطوات العملية، راجع <a href=\"/ar/blog/kayfiyya-tadweer-wa-qalb-as-sura/\">كيف تدور أو تقلب صورة</a> والدليل الكامل في <a href=\"/ar/blog/dalil-tadweer-wa-qalb-as-suwar/\">تدوير وقلب الصور: دليل كامل</a>. وإذا حملت صورتك أيضًا بيانات موقع تفضل إزالتها، اقرأ <a href=\"/ar/blog/makhatir-khususiyyat-as-suwar-gps-exif/\">مخاطر خصوصية الصور: GPS وEXIF والبيانات الوصفية</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ما اتجاه EXIF بكلمات بسيطة؟","answer":"إنه رقم محفوظ داخل صورة يسجل كيف كانت الكاميرا ممسوكة: عارضات تقرأ الرقم تعرض الصورة صحيحًا، بينما عارضات تتجاهله تعرض البكسلات كما هي، فتبدو الصورة مائلة."},{"question":"لماذا تبدو صورتي جيدة على هاتفي ومائلة على موقع؟","answer":"معرض هاتفك يقرأ ملاحظة اتجاه EXIF، لكن الموقع لا يقرأها: البكسلات لم تُدوّر أبدًا، فالموقع يعرضها في اتجاهها الأصلي. وتدوير الصورة في محرر يعيد كتابة البكسلات ويصلح المشكلة إلى الأبد."},{"question":"هل صورة مائلة تالفة أو فاسدة؟","answer":"لا، البكسلات سليمة والملف سليم: المشكلة فقط أن برنامجًا يقرأ ملاحظة الاتجاه وآخر لا يقرأها. وتصحيح دوران منفذ جيدًا يجعل الملف يُعرض جيدًا في كل مكان."},{"question":"كيف أصحح إلى الأبد صورة باتجاه خطأ؟","answer":"دوّر البكسلات الحقيقية في محرر وصدّر النتيجة، ما يعيد تعيين قيمة الاتجاه إلى عادي: أداة تدوير وقلب الصور تفعل هذا: الملف المنزّل له بكسلات موجهة صحيحًا وملصق اتجاه نظيف."},{"question":"هل تحويل HEIC إلى JPG يسبب مشاكل اتجاه؟","answer":"قد يسبب، إذا نسخ المحول البكسلات لكنه فقد ملاحظة اتجاه EXIF: الترتيب الأكثر أمانًا هو تصحيح الاتجاه أولًا ثم تحويل الملف المصحح. وإذا بدا ملف محول أصلًا مائلًا، دوّر الملف المحول مباشرة."},{"question":"هل تستطيع بيانات EXIF كشف أين التُقطت صورتي؟","answer":"نعم، نفس البيانات الوصفية التي تحفظ الاتجاه قد تحفظ أيضًا إحداثيات GPS وموديل الكاميرا والتاريخ: تدوير صورة في أداة CompressMyPic يزيل وسوم GPS عند التصدير، وإزالة البيانات الوصفية تزيلها كلها."}];
